class OperationParser {
    constructor(content) {
        this.content = content;
    }

    parse() {
        const operations = [];
        const operationRegex = /\{([^}]+)\}/g;
        let match;

        while ((match = operationRegex.exec(this.content)) !== null) {
            const operationText = match[1];
            const operation = this.parseObject(operationText);
            operations.push(operation);
        }

        return operations;
    }

    parseArray(arrayString) {
        const elements = [];
        let currentElement = "";
        let nestedLevel = 0;

        for (let i = 1; i < arrayString.length - 1; i++) {
            const char = arrayString[i];

            if (char === "[" || char === "{") nestedLevel++;
            if (char === "]" || char === "}") nestedLevel--;

            if (char === "," && nestedLevel === 0) {
                elements.push(this.parseValue(currentElement.trim()));
                currentElement = "";
            } else {
                currentElement += char;
            }
        }

        if (currentElement.trim()) {
            elements.push(this.parseValue(currentElement.trim()));
        }

        return elements;
    }

    parseObject(objectString) {
        const object = {};
        const keyValueRegex = /"(\w+)":\s*(\[.*?\]|\{.*?\}|-?\d+(\.\d+)?|"[^"]+")/g;
        let match;

        while ((match = keyValueRegex.exec(objectString)) !== null) {
            const key = match[1];
            const value = this.parseValue(match[2]);
            object[key] = value;
        }

        return object;
    }

    parseValue(valueString) {
        if (valueString.startsWith("[")) {
            return this.parseArray(valueString);
        } else if (valueString.startsWith("{")) {
            return this.parseObject(valueString);
        } else if (!isNaN(valueString)) {
            return parseFloat(valueString);
        } else {
            return valueString.replace(/"/g, "");
        }
    }
}


export { OperationParser };
